// Builds tuning/CATALOG.md: every item, piece of equipment, monster and level with its numbers,
// computed values (sell price, encounter rate, kills per level...) and links to its art files.
// Generated by `npm run tuning`; never edit the catalog by hand.

const TICKS = 10;
const sec = (ticks) => `${+(ticks / TICKS).toFixed(1)} s`;
const pct = (f) => `${+(f * 100).toFixed(2)}%`;
const img = (path, w) => `<img src="../${path}" width="${w}">`;
const link = (path) => `[${path.slice(path.lastIndexOf('/') + 1)}](../${path})`;
const CLASS_NAMES = { knight: '騎士', elf: '妖精', mage: '法師' };
const SLOT_NAMES = { weapon: '武器', shield: '盾牌', helmet: '頭盔', armor: '盔甲', cloak: '斗篷', gloves: '手套', boots: '靴子' };

function table(header, rows) {
  return [`| ${header.join(' | ')} |`, `|${header.map(() => '---').join('|')}|`, ...rows.map((r) => `| ${r.join(' | ')} |`)].join('\n');
}

function objectsOf(map) {
  return map.layers.filter((l) => l.type === 'objectgroup').flatMap((l) => l.objects);
}

function spawnsOf(maps, strings) {
  const out = [];
  for (const [mapId, map] of Object.entries(maps)) {
    const mapName = strings[map.properties?.find((p) => p.name === 'nameKey')?.value] ?? mapId;
    for (const o of objectsOf(map)) {
      if ((o.type || o.class) !== 'spawn') continue;
      const p = (n) => o.properties?.find((x) => x.name === n)?.value;
      const min = Number(p('respawnSec'));
      const max = Number(p('respawnMaxSec') ?? min);
      const tiles = (o.width / map.tilewidth) * (o.height / map.tileheight);
      out.push({ mapId, mapName, spawn: o.name, monster: p('monster'), count: Number(p('count')), min, max, tiles });
    }
  }
  return out;
}

function respawnText(min, max) {
  const f = (s) => (s >= 3600 ? `${+(s / 3600).toFixed(2)} h` : s >= 60 ? `${+(s / 60).toFixed(1)} min` : `${s} s`);
  return min === max ? f(min) : `${f(min)}–${f(max)}`;
}

/** Upper bound if every monster dies the moment it appears: count x 3600 / average respawn. */
function maxKillsPerHour(sp) {
  const avg = (sp.min + sp.max) / 2;
  return avg > 0 ? (sp.count * 3600) / avg : Infinity;
}

export function buildCatalog({ items, monsters, spells, classes: classDefs, totalExp, strings, maps, balance, shops, npcs }) {
  const s = (k) => strings[k] ?? k;
  const name = (id) => s(items[id]?.nameKey ?? id);
  const sellRatio = balance.sellRatio;
  const soldBy = (id) => Object.entries(npcs ?? {})
    .filter(([, n]) => n.shop && shops[n.shop]?.items.includes(id)).map(([, n]) => s(n.nameKey)).join('、') || '—';
  const classes = (d) => (d.classes ? d.classes.map((c) => CLASS_NAMES[c]).join('、') : '全部');
  const spawns = spawnsOf(maps, strings);
  const out = [];

  out.push(`# Tuning catalog（遊戲數值總表）

> **Generated by \`npm run tuning\`. Don't edit this file**: edit the CSV sheets in this folder
> (see [README.md](README.md)), then run \`npm run tuning\` again.
> Art: click a file link to open it; how to make replacements is in [ASSETS.md](../assets/ASSETS.md).

Contents: [Items](#items) · [Equipment](#equipment) · [Spells](#spells) · [Monsters](#monsters) · [Encounter rates](#encounter-rates) · [Exp table](#exp-table)
`);

  // ---------------------------------------------------------------- items
  out.push(`## Items

Sheet: [items.csv](items.csv). Sell price = buy price × ${sellRatio}, rounded down for the whole batch sold (so 200 arrows at 0.5 give 100). Potions in the same cooldown group share one cooldown.
`);
  const effect = (d) => {
    const u = d.use;
    if (d.kind === 'ammo') return `箭傷害 +${d.arrowDamage ?? 0}`;
    if (!u) return '—';
    if (u.type === 'heal') return [u.hp ? `HP +${u.hp}` : '', u.mp ? `MP +${u.mp}` : ''].filter(Boolean).join(' ');
    if (u.type === 'maxDamage') return `最大傷害 ${sec(u.ticks)}`;
    return { return: '回到村莊', teleport: '隨機傳送', save: '記錄進度' }[u.type] ?? u.type;
  };
  out.push(table(['Icon', 'Item', 'Effect', 'Cooldown', 'Classes', 'Weight', 'Buy / Sell', 'Sold by', 'Icon file'],
    Object.entries(items).filter(([id, d]) => id !== '_comment' && d.kind !== 'equipment' && d.kind !== 'spellbook').map(([id, d]) => [
      img(`assets/sprites/icons/${d.icon}.png`, 32), `${s(d.nameKey)}<br>\`${id}\``, effect(d),
      d.cooldownGroup ? `${sec(d.cooldownTicks)} (${d.cooldownGroup})` : '—', classes(d), +(d.weight / 10).toFixed(1),
      `${d.price} / ${+(d.price * sellRatio).toFixed(2)}`, soldBy(id), link(`assets/sprites/icons/${d.icon}.png`),
    ])));

  // ---------------------------------------------------------------- equipment
  out.push(`
## Equipment

Sheet: [equipment.csv](equipment.csv). "Safe +" is the enhancement level that always succeeds
(hidden from players). Damage is before the player's STR/DEX bonus, arrows and the target's Def.
`);
  out.push(table(['Icon', 'Item', 'Slot', 'Classes', 'Lv', 'Attack', 'Def / MR', 'Durability', 'Safe +', 'Weight', 'Buy / Sell', 'Files'],
    Object.entries(items).filter(([, d]) => d.kind === 'equipment').map(([id, d]) => {
      const w = d.weapon;
      const attack = w
        ? `${w.dmg[0]}–${w.dmg[1]}, hit ${w.hit}%, ${sec(w.attackTicks)}${w.range > 1 ? `, range ${w.range}` : ''}${w.twoHanded ? ', 2-handed' : ''} (${w.anim})`
        : '—';
      return [
        img(`assets/sprites/icons/${d.icon}.png`, 32), `${s(d.nameKey)}<br>\`${id}\``, SLOT_NAMES[d.slot], classes(d), d.level ?? 1,
        attack, `${d.def ?? 0} / ${d.mr ?? 0}%`, w ? w.durability : '—', `+${d.safeEnchant}`, +(d.weight / 10).toFixed(1),
        `${d.price} / ${+(d.price * sellRatio).toFixed(2)}`,
        [link(`assets/sprites/icons/${d.icon}.png`), d.sprite ? link(`assets/sprites/characters/${d.sprite}.png`) : ''].filter(Boolean).join('<br>'),
      ];
    })));

  // ---------------------------------------------------------------- spells
  const learnAt = (sp) => Object.entries(classDefs ?? {}).map(([cls, def]) => {
    const rule = def.magic?.[sp.school];
    if (!rule || sp.magicLevel > rule.max) return null;
    const lv = rule.min !== undefined && sp.magicLevel <= rule.min ? 1 : sp.magicLevel * rule.every;
    return `${CLASS_NAMES[cls]} Lv ${lv}`;
  }).filter(Boolean).join('<br>') || '—';
  const spellEffect = (e) => ({
    heal: () => `HP +${e.min}–${e.max}`,
    damage: () => `傷害 ${e.min}–${e.max}`,
    aoe: () => `範圍 ${e.radius} 格 傷害 ${e.min}–${e.max}`,
    maxDamage: () => `最大傷害 ${sec(e.ticks)}`,
    buffDef: () => `防禦 +${e.amount}, ${sec(e.ticks)}`,
    buffMr: () => `魔防 +${e.amount}%, ${sec(e.ticks)}`,
  })[e.type]?.() ?? e.type;
  const classRules = Object.entries(classDefs ?? {}).map(([cls, def]) => {
    const r = Object.entries(def.magic ?? {}).map(([school, rule]) =>
      `${school === 'elf' ? '精靈魔法' : '一般魔法'} +1 級 / ${rule.every} 等級 (最高 ${rule.max} 級${rule.min ? `, 出生即有 ${rule.min} 級` : ''})`);
    return `- ${CLASS_NAMES[cls]}: ${r.join('; ') || '無法學習魔法'}`;
  });
  out.push(`
## Spells

Sheet: [spells.csv](spells.csv). Each spell is learned by using its book (\`book_<id>\`, generated
from the same row). Who can learn what is set by \`magic\` in \`data/classes.json\`:

${classRules.join('\n')}

Magic damage is the roll plus the INT bonus, always hits, and is reduced by the target's MR.
`);
  out.push(table(['Icon', 'Spell', 'School / Lv', 'Effect', 'MP', 'Cooldown / Cast', 'Range', 'Learn at', 'Book', 'Sold by', 'Icon file'],
    Object.entries(spells ?? {}).filter(([id]) => id !== '_comment').map(([id, sp]) => [
      img(`assets/sprites/icons/${sp.icon}.png`, 32), `${s(sp.nameKey)}<br>\`${id}\``,
      `${sp.school === 'elf' ? '精靈' : '一般'} ${sp.magicLevel}`, spellEffect(sp.effect), sp.mp,
      `${sec(sp.cooldownTicks)} / ${sec(sp.castTicks)}`, sp.target === 'enemy' ? sp.range : '自身', learnAt(sp),
      `${items[sp.book]?.price ?? '—'} 金幣`, soldBy(sp.book), link(`assets/sprites/icons/${sp.icon}.png`),
    ])));

  // ---------------------------------------------------------------- monsters
  out.push(`
## Monsters

Sheets: [monsters.csv](monsters.csv), [drops.csv](drops.csv), [spawns.csv](spawns.csv). Where a
monster lives and how many there are is set per spawn area (see [Encounter rates](#encounter-rates)).
`);
  out.push(table(['Monster', 'Lv', 'HP', 'Attack', 'Hit / Evasion', 'Def / MR', 'Behaviour', 'Exp', 'Align', 'Found in'],
    Object.entries(monsters).filter(([id]) => id !== '_comment').map(([id, m]) => [
      `[${s(m.nameKey)}](#${id})${m.boss ? ' 👑' : ''}`, m.level, m.hp, `${m.dmg[0]}–${m.dmg[1]} / ${sec(m.attackTicks)}`,
      `${m.hit}% / ${m.evasion}%`, `${m.def} / ${m.mr}%`, m.aggressive ? `aggressive (${m.aggroRange} tiles)` : 'passive',
      m.exp, m.alignment, spawns.filter((x) => x.monster === id).map((x) => x.mapName).filter((v, i, a) => a.indexOf(v) === i).join('、') || '—',
    ])));
  for (const [id, m] of Object.entries(monsters)) {
    if (id === '_comment') continue;
    const sheet = `assets/sprites/monsters/${m.sprite}.png`;
    const where = spawns.filter((x) => x.monster === id).map((x) => {
      const rate = m.boss ? `boss: appears again ${respawnText(x.min, x.max)} of play time after it dies`
        : `≤ ${Math.round(maxKillsPerHour(x))} kills/hour if every one dies at once`;
      return `- ${x.mapName} (area \`${x.spawn}\`): up to **${x.count}** at a time, respawn **${respawnText(x.min, x.max)}**, 1 per ${Math.round(x.tiles / Math.max(1, x.count))} tiles; ${rate}`;
    });
    const drops = [`- 金幣 ${m.gold[0]}–${m.gold[1]} (always)`, ...m.drops.map((d) => {
      const n = d.count ? `×${d.count[0]}–${d.count[1]}` : '×1';
      return `- ${name(d.itemId)} ${n}: **${pct(d.chance)}** (≈ ${+(d.chance * 100).toFixed(1)} per 100 kills)`;
    })];
    out.push(`
### ${s(m.nameKey)} \`${id}\`${m.boss ? ' 👑 boss' : ''} <a id="${id}"></a>

${img(sheet, m.frame && m.frame > 64 ? 288 : 192)}<br>Sprite: ${link(sheet)}

| Lv | HP | Attack | Hit / Evasion | Def / MR | Move | Leash | Exp | Alignment |
|---|---|---|---|---|---|---|---|---|
| ${m.level} | ${m.hp} | ${m.dmg[0]}–${m.dmg[1]} every ${sec(m.attackTicks)} | ${m.hit}% / ${m.evasion}% | ${m.def} / ${m.mr}% | ${sec(m.stepTicks)} per tile | ${m.leashRange} tiles | ${m.exp} | ${m.alignment} |

**Found in**
${where.join('\n') || '- nowhere yet (add a row to spawns.csv and a spawn area in Tiled)'}

**Drops**
${drops.join('\n')}
`);
  }

  // ---------------------------------------------------------------- encounter rates
  out.push(`
## Encounter rates

How often a player meets each monster, per spawn area. "Max kills/hour" assumes every monster
dies the moment it appears, so real numbers are lower; it shows how much a spot can give.
Areas are drawn in Tiled; the numbers come from [spawns.csv](spawns.csv).
`);
  out.push(table(['Map', 'Area', 'Monster', 'Max alive', 'Respawn', 'Area size', 'Density', 'Max kills/h', 'Max Exp/h'],
    spawns.map((x) => {
      const m = monsters[x.monster];
      const k = maxKillsPerHour(x);
      return [x.mapName, `\`${x.spawn}\``, s(m?.nameKey ?? x.monster), x.count, respawnText(x.min, x.max), `${x.tiles} tiles`,
        `1 per ${Math.round(x.tiles / Math.max(1, x.count))} tiles`, m?.boss ? `≈ ${+k.toFixed(2)}` : Math.round(k),
        Math.round(k * (m?.exp ?? 0))];
    })));

  // ---------------------------------------------------------------- exp
  const refs = Object.entries(monsters).filter(([id, m]) => id !== '_comment' && !m.boss).sort((a, b) => a[1].level - b[1].level);
  out.push(`
## Exp table

Sheet: [exp.csv](exp.csv). Death costs ${balance.deathExpLossPct}% of the current level's span (never
below level ${balance.deathLevelFloor}). The kill columns show how many of each monster one level takes.
`);
  out.push(table(['Lv', 'Exp to next', 'Total Exp', 'Death loss', ...refs.map(([, m]) => `${s(m.nameKey)} (${m.exp})`)],
    totalExp.slice(1).map((total, i) => {
      const span = total - totalExp[i];
      return [i + 1, span.toLocaleString('en'), total.toLocaleString('en'), Math.floor((span * balance.deathExpLossPct) / 100).toLocaleString('en'),
        ...refs.map(([, m]) => Math.ceil(span / Math.max(1, m.exp)).toLocaleString('en'))];
    })));
  out.push('');
  return out.join('\n');
}
